mapper.insert:
INSERT INTO SYT1MG
    ( CORP_GR
    , TR_YMD
    , TR_CD
    , FUND_CD
    , TR_CO_CD
    , TRUSTEE
    , JM_CD
    , CURRENCY
    , TR_SEQ
    , TR_JUSU
    , TR_DANGA
    , TR_COST
    , TR_AEK
    , GYULJE_YMD
    , GYULJE_JM_CD
    , TRANS_RT
    , UPD_USER
    )
VALUES
    ( #{corpGr}
    , TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
    , #{trCd, jdbcType=VARCHAR}
    , #{fundCd, jdbcType=VARCHAR}
    , #{trCoCd, jdbcType=VARCHAR}
    , #{trustee, jdbcType=VARCHAR}
    , #{yjCd, jdbcType=VARCHAR}
    , #{currency, jdbcType=VARCHAR}
    , #{trSeq}
    , #{trJusu, jdbcType=NUMERIC}
    , #{trDanga, jdbcType=NUMERIC}
    , #{trCost, jdbcType=NUMERIC}
    , #{trAek, jdbcType=NUMERIC}
    , CASE WHEN #{gyuljeYmd} IS NOT NULL AND #{gyuljeYmd} != ''
           THEN TO_DATE(REPLACE(#{gyuljeYmd}, '-', ''), 'YYYYMMDD')
           ELSE NULL END
    , #{gyuljeJmCd, jdbcType=VARCHAR}
    , #{transRt, jdbcType=NUMERIC}
    , #{updUser, jdbcType=VARCHAR}
    )

mapper.update:
UPDATE SYT1MG
   SET TR_CD        = #{trCd, jdbcType=VARCHAR}
     , FUND_CD      = #{fundCd, jdbcType=VARCHAR}
     , TR_CO_CD     = #{trCoCd, jdbcType=VARCHAR}
     , TRUSTEE      = #{trustee, jdbcType=VARCHAR}
     , JM_CD        = #{yjCd, jdbcType=VARCHAR}
     , CURRENCY     = #{currency, jdbcType=VARCHAR}
     , TR_JUSU      = #{trJusu, jdbcType=NUMERIC}
     , TR_DANGA     = #{trDanga, jdbcType=NUMERIC}
     , TR_COST      = #{trCost, jdbcType=NUMERIC}
     , TR_AEK       = #{trAek, jdbcType=NUMERIC}
     , GYULJE_YMD   = CASE WHEN #{gyuljeYmd} IS NOT NULL AND #{gyuljeYmd} != ''
                           THEN TO_DATE(REPLACE(#{gyuljeYmd}, '-', ''), 'YYYYMMDD')
                           ELSE NULL END
     , GYULJE_JM_CD = #{gyuljeJmCd, jdbcType=VARCHAR}
     , TRANS_RT     = #{transRt, jdbcType=NUMERIC}
     , UPD_USER     = #{updUser, jdbcType=VARCHAR}
 WHERE CORP_GR      = #{corpGr}
   AND TR_YMD       = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
   AND TR_SEQ       = #{trSeq}

mapper.delete:
DELETE FROM SYT1MG
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
   AND TR_SEQ  = #{trSeq}

mapper.select:
SELECT TO_CHAR(MAX(TR_YMD), 'YYYY-MM-DD')
  FROM SYT1MG
 WHERE CORP_GR = #{corpGr}
